\u0062\u0074\u0035\u0025\u0033\u003c\u0061\u0032\u003c\u0063\u0031\u005b\u0038\u004d\u002b\u0051\u003d\u007e\u0028\u005e\u002f\u0059\u005e\u002e\u0035\u0068\u0066\u0074\u0028\u0038\u004a\u007e\u004f\u0050\u005e\u0038\u0076\u0051\u0047\u0042\u002a\u003a\u0038\u002a\u0036\u0079\u0054\u0075\u0046\u004c\u0043\u0029\u002a\u0066\u0050\u004f\u004b\u0026\u003b\u0049\u0073\u006c\u0079\u0034\u0063\u004f\u0071\u005b\u0067\u0037\u0028\u0073\u005f\u004e\u0057\u004b\u0024\u0035\u0066\u0033\u0060\u0064\u002c\u0053\u003e\u005b\u006b\u0043\u007d\u006c\u002a\u007d\u005e\u0032\u002f\u0036\u0063\u004b\u0070\u004e\u0073\u0059\u0035\u0077\u0063\u0073\u0063\u003a\u006b\u0025\u0060\u007a\u0033\u0048\u007b\u0024\u003f\u003b\u0040\u007a\u0038\u003b\u0048\u0023\u0034\u002b\u007b\u002b\u0032\u007e\u005d\u0029\u007d\u002e\u0023\u0036\u007d\u0062\u005f\u007c\u0055\u0064\u006a\u005b\u0043\u0022\u0074\u002f\u0024\u0068\u0030\u0064\u002e\u0044\u002b\u002a\u0071\u007a\u005e\u0068\u002a\u005e\u002a\u006f\u007e\u0057\u0023\u0036\u0052\u0040\u004d\u006d\u003f\u004d\u0046\u0026\u0065\u004a\u002e\u0075\u0064\u002e\u002e\u0036\u0050\u0040\u0023\u003f\u003e\u002f\u0043\u004b\u007a\u0045\u0021\u007d\u003f\u006e\u0076\u0079\u0058\u002e\u007c\u004e\u002f\u005f\u0066\u007b\u004c\u0073\u003c\u006d\u0034\u003b\u003d\u006e\u0055\u004f\u0022\u0049\u0073\u0066\u006f\u005e\u002c\u0022\u003d\u0079\u0049\u0063\u0023\u0047\u0028\u0052\u003f\u0024\u0061\u0048\u004a\u0062\u0043\u0056\u0073\u0047\u003c\u0075\u0045\u0048\u0072\u002e\u0051\u0035\u005b\u002c\u0031\u0033\u0033\u003b\u0039\u0068\u0046\u0078\u0037\u0022\u0078\u0035\u0045\u0065\u0064\u0032\u0030\u0062\u0050\u0069\u006b\u005b\u0044\u0022\u0038\u005b\u0040\u004d\u0021\u0026\u006c\u0074\u005e\u002a\u0058\u0069\u0044\u0039\u0035\u0068\u0069\u004d\u0068\u0071\u003d\u0033\u0028\u0040\u005f\u0023\u0050\u0062\u0030\u0030\u0051\u002c\u0072\u003a\u0066\u005f\u0062\u0033\u003b\u0077\u003a\u0026\u0041\u005f\u0021\u007c\u0032\u0036\u0079\u0026\u006e\u0051\u0038\u0028\u0079\u0074\u0043\u0052\u004a\u0038\u004f\u003f\u0040\u0026\u0070\u0068\u005e\u0052\u0065\u0054\u003f\u0074\u006c\u0046\u0058\u0056\u0069\u0043\u0040\u0048\u005e\u0021\u0029\u0052\u0065\u0054\u003f\u0044\u0048\u007a\u0039\u004a\u0034\u0070\u0072\u0058\u0033\u0046\u0061\u0031\u0055\u0021\u0066\u002a\u0074\u0061\u007c\u006c\u0073\u0053\u0062\u0039\u004e\u0071\u0074\u0029\u007d\u0073\u0076\u003c\u0077\u0026\u0053\u0035\u0055\u0062\u0041\u007c\u002e\u003d\u0035\u0029\u0038\u0073\u0031\u0052\u003d\u002a\u003b\u003a\u0072\u002f\u0041\u007c\u002a\u0056\u0045\u007a\u004c\u004d\u005f\u0053\u003a\u0048\u0039\u0078\u0079\u005b\u006d\u002e\u002a\u0028\u0035\u007e\u0052\u0063\u0034\u003b\u0047\u0077\u007c\u002f\u0059\u0045\u002f\u0078\u004d\u0039\u003a\u0029\u0023\u006e\u006b\u004f\u0072\u004e\u0043\u003f\u0077\u0035\u0048\u005f\u0021\u0058\u006d\u0063\u0024\u0036\u0049\u0021\u0031\u004b\u0063\u0031\u0060\u0063\u006f\u0075\u0064\u003c\u003a\u0079\u007c\u0052\u0021\u0044\u0023\u0026\u004b\u0038\u004f\u007c\u0068\u0039\u002c\u0077\u0049\u0025\u0032\u004c\u0026\u0046\u0036\u006d\u0025\u0038\u003d\u0039\u0067\u0043\u0025\u003c\u0075\u004b\u004f\u0045\u0056\u0062\u005a\u0026\u0078\u0068\u0057\u005e\u004d\u0060\u006b\u003e\u002a\u004b\u006c\u002c\u0042\u0045\u0079\u007d\u005d\u0048\u0023\u006c\u0056\u0030\u005f\u002c\u0060\u002f\u0056\u0028\u0066\u0038\u0024\u0056\u0037\u0061\u0054\u0076\u0063\u0060\u0023\u004e\u0068\u004d\u002c\u0070\u002c\u002e\u006b\u0076\u004c\u0075\u003f\u0022\u0066\u004d\u007d\u0058\u0023\u004d\u002e\u007b\u0074\u0021\u0053\u0052\u0073\u002a\u005d\u0022\u0053\u003b\u002a\u0064\u0054\u0033\u006b\u0076\u0079\u0068\u0031\u004c\u0038\u0073\u004b\u003f\u003b\u006f\u0047\u005e\u0046\u0039\u0023\u0079\u0044\u005b\u0045\u0044\u0032\u0076\u0026\u0054\u0056\u0054\u005d\u0063\u0023\u007a\u0072\u006e\u0021\u006d\u006d\u0056\u0071\u0044\u0025\u0021\u0050\u0060\u0057\u0022\u0044\u0045\u0068\u0025\u007e\u005b\u0052\u006a\u0065\u0034\u0023\u004e\u002a\u002f\u0065\u0032\u002f\u0058\u003b\u007d\u007d\u0040\u0061\u0029\u005a\u0077\u0075\u007c\u0036\u0077\u007c\u0032\u0058\u0065\u006e\u003b\u002e\u006c\u004d\u0038\u002f\u0074\u0050\u0024\u003e\u0074\u0070\u0045\u0035\u002e\u004c\u003b\u007c\u004f\u005a\u0051\u004f\u0055\u0074\u0044\u0048\u0043\u0068\u004c\u0026\u0054\u0040\u006e\u0060\u0071\u0034\u005d\u0037\u0072\u0079\u0061\u0043\u005e\u002a\u007c\u004e\u0039\u0074\u004e\u0072\u0076\u0042\u006e\u0021\u0066\u002a\u0035\u007e\u0051\u0063\u004d\u0075\u0047\u0046\u0039\u0023\u0079\u0044\u005b\u0045\u0044\u004a\u006b\u0063\u0053\u0058\u0073\u0046\u0039\u0023\u0079\u0044\u005b\u005a\u002a\u0025\u0039\u0039\u0079\u004a\u005b\u0067\u0047\u0052\u007c\u002a\u003e\u0053\u006a\u005e\u0062\u0051\u0078\u0021\u0058\u004b\u004a\u003c\u0029\u0070\u0068\u0033\u003f\u0059\u005b\u0046\u004c\u002c\u0038\u006e\u0068\u005e\u0068\u0028\u0028\u0068\u006b\u0044\u004c\u0043\u006a\u0032\u006e\u003a\u0054\u0072\u007d\u002b\u0036\u0042\u0051\u0035\u004a\u004f\u0074\u006d\u0021\u0063\u002a\u0037\u003d\u0035\u0025\u004e\u002a\u0038\u0058\u0076\u003f\u005b\u006b\u0022\u005a\u0031\u0076\u003e\u005d\u0054\u0029\u0049\u0054\u0068\u0028\u0028\u0068\u006b\u0044\u0028\u005d\u0072\u006c\u003a\u006b\u005d\u0048\u006c\u0077\u0063\u002f\u0058\u005d\u007d\u005a\u0043\u0056\u0035\u0034\u0054\u005f\u0050\u0043\u0022\u002e\u007b\u002a\u0055\u0035\u0057\u0061\u0030\u005e\u0038\u0070\u004e\u0045\u0064\u0034\u0073\u0061\u0077\u006c\u0048\u004b\u0047\u004d\u0055\u0022\u0056\u0021\u0040\u007b\u0064\u0061\u007d\u003e\u003a\u0052\u0062\u0037\u0041\u0064\u004a\u0040\u0056\u002c\u0071\u0025\u0056\u0021\u0064\u0036\u0023\u0073\u0060\u006e\u0064\u002b\u0031\u005e\u0069\u006f\u0022\u0054\u0045\u0023\u0074\u0078\u004c\u0039\u004d\u0048\u007b\u0071\u0021\u0061\u0026\u0071\u0051\u0068\u0055\u0053\u007e\u0068\u0041\u0030\u005e\u005f\u0075\u0022\u007d\u0073\u0028\u0040\u006f\u0071\u0044\u0023\u0054\u007b\u005b\u007b\u004f\u0021\u007d\u0073\u0031\u0043\u0076\u0025\u0067\u0028\u002a\u0049\u0074\u0049\u0034\u0053\u002c\u0024\u0024\u002c\u0042\u0039\u002a\u007b\u0075\u003d\u0073\u0033\u005a\u0050\u0063\u0048\u0054\u006b\u0052\u0036\u0065\u0021\u007c\u007c\u0025\u0069\u003c\u0034\u0024\u0035\u003c\u004a\u0025\u0065\u006c\u0065\u002a\u0074\u0029\u007d\u0073\u0076\u003c\u0077\u0026\u0053\u0035\u0055\u0062\u0041\u007c\u002e\u003d\u0035\u0029\u0038\u0073\u0031\u0052\u003d\u002a\u003b\u003a\u0072\u002f\u0044\u0075\u006a\u0069\u0031\u004c\u0038\u0073\u0066\u0059\u0032\u0057\u007e\u0053\u0041\u007b\u006d\u004d\u0046\u005b\u0058\u0044\u004a\u0067\u0044\u0039\u0035\u0068\u0069\u004d\u0078\u002a\u0053\u0074\u0053\u0033\u004d\u0041\u0021\u003d\u006e\u0034\u0029\u0072\u005e\u0071\u0048\u003b\u0067\u0039\u0051\u003e\u0026\u0048\u006d\u0038\u0049\u004f\u0057\u005f\u0071\u002c\u0055\u002e\u0054\u0051\u0054\u0066\u005f\u0053\u0046\u0075\u003e\u003d\u0072\u0065\u0071\u006b\u003a\u0052\u002f\u004f\u0050\u0028\u0049\u0025\u003c\u006d\u0048\u003f\u006a\u002b\u0051\u007a\u0074\u003d\u002a\u0068\u0022\u0047\u006c\u003e\u0047\u0078\u005b\u0043\u0073\u005b\u003d\u002a\u0026\u005b\u004d\u004a\u0071\u0060\u0050\u0073\u0072\u003c\u0062\u002a\u0039\u0043\u0064\u003a\u0029\u004d\u0025\u003e\u0030\u004e\u0047\u0034\u0053\u0032\u0065\u0026\u0026\u0037\u0054\u0068\u0073\u006e\u0042\u002a\u0026\u006f\u007d\u0066\u0073\u0073\u007b\u003b\u007b\u0073\u0029\u003f\u0062\u0064\u0043\u004a\u006b\u004b\u0021\u005e\u002f\u0054\u0074\u0043\u0042\u0066\u0054\u003c\u0037\u0033\u005a\u005f\u0075\u0033\u0053\u0055\u0025\u006b\u006e\u002e\u0022\u0061\u0055\u0065\u0061\u0032\u0076\u005e\u0071\u0041\u002a\u006f\u0059\u0077\u003c\u006e\u0022\u003f\u0044\u0057\u0036\u0028\u0064\u0079\u006f\u007e\u0046\u007b\u0038\u007b\u0066\u0069\u003d\u003e\u0058\u0061\u0022\u0037\u007e\u0054\u0036\u003c\u0049\u005d\u005f\u0058\u0032\u0054\u005e\u002f\u0058\u0058\u0048\u0022\u004c\u0044\u0053\u0043\u0078\u006b\u003f\u0058\u003b\u0041\u003f\u006a\u0033\u0052\u0061\u004c\u0038\u004f\u002c\u0079\u006f\u007a\u0044\u006d\u0063\u0066\u0044\u0075\u005b\u0035\u0042\u002b\u003c\u0069\u0070\u0044\u0060\u0049\u0062\u0077\u0068\u006f\u005f\u0023\u0053\u005a\u0055\u003d\u002f\u003c\u003b\u004f\u0070\u0022\u0021\u0024\u003e\u0049\u0055\u007c\u0065\u0021\u004a\u0065\u0076\u0045\u005e\u002b\u004a\u003f\u006b\u0066\u0023\u0044\u0021\u004d\u0065\u0045\u007c\u0037\u004d\u007c\u003a\u0042\u0061\u0041\u0071\u004b\u004d\u0048\u006f\u0052\u0039\u0071\u007a\u003f\u002b\u0056\u002e\u0071\u003a\u0063\u0066\u003c\u0071\u004a\u004a\u003f\u0056\u0052\u0049\u006f\u0079\u0072\u0075\u004e\u0063\u004b\u0062\u004b\u0030\u0069\u004f\u007a\u007c\u0050\u0058\u0026\u0043\u0024\u0036\u0065\u0032\u0054\u0054\u002f\u0074\u004d\u0069\u0069\u007d\u0048\u0058\u006d\u006c\u007b\u0029\u0026\u004c\u0044\u0066\u0040\u004e\u0059\u0062\u004d\u004e\u0078\u0066\u0049\u0056\u0035\u003c\u0044\u0033\u0033\u003e\u0031\u0057\u004d\u004d\u003d\u0078\u0061\u0071\u0048\u0038\u0066\u0046\u003b\u0038\u0041\u0041\u006e\u003c\u0072\u0038\u003c\u0049\u0053\u0025\u0043\u004e\u006f\u0076\u0062\u005b\u004d\u0040\u0074\u0073\u002f\u0032\u0031\u0038\u0055\u0077\u0073\u004d\u0038\u002a\u007a\u0043\u0053\u0035\u007b\u0024\u0055\u003a\u004b\u005a\u005a\u0023\u005f\u0038\u0055\u0078\u0069\u006a\u006e\u0056\u0073\u004d\u0038\u002a\u007a\u0043\u0044\u006e\u0034\u0021\u003b\u005e\u006b\u0040\u0038\u0049\u0044\u0035\u0030\u0067\u007c\u0026\u007e\u004e\u007d\u0078\u0040\u0075\u0021\u0035\u0035\u0029\u0070\u0039\u0026\u0064\u006e\u0050\u0069\u0069\u002a\u0033\u0021\u004e\u006f\u007c\u0063\u0076\u0031\u0065\u0030\u0022\u0071\u0055\u0030\u0054\u004c\u0077\u0058\u0076\u0031\u0065\u0030\u0022\u0071\u007c\u0040\u0071\u0033\u0044\u004a\u005e\u0057\u007c\u006b\u0071\u007c\u0056\u0049\u0026\u0064\u003b\u0064\u0070\u004b\u0055\u0037\u004a\u003b\u005e\u0029\u005b\u004e\u0071\u004e\u0035\u0054\u0054\u0045\u0043\u006a\u0039\u006e\u0043\u0061\u002e\u007a\u0052\u005f\u007b\u0022\u006b\u0059\u007b\u0038\u0075\u003b\u0046\u006b\u007c\u006a\u003d\u0034\u003e\u0031\u0036\u003e\u006a\u002e\u0061\u0069\u0075\u003b\u0029\u0024\u003c\u0035\u002f\u0023\u0059\u0060\u0038\u0072\u007b\u0023\u0030\u0057\u003c\u0063\u0074\u006f\u0048\u003b\u0028\u003c\u0069\u003d\u0077\u0073\u004e\u0032\u005f\u0048\u003f\u0033\u002e\u0056\u0075\u0048\u0021\u004d\u0037\u003d\u0077\u0073\u004e\u0029\u0032\u003a\u003e\u003a\u0071\u0066\u0071\u003b\u0054\u004d\u005e\u0064\u004b\u0053\u005d\u004d\u005f\u0043\u0033\u0024\u007d\u007d\u0038\u0075\u003b\u002b\u004c\u0075\u004a\u0021\u0043\u0075\u006e\u005e\u003d\u006a\u0046\u0069\u0057\u005b\u0022\u0036\u0032\u0038\u0069\u003c\u0075\u002e\u002a\u003c\u0035\u005f\u0046\u0033\u007d\u007c\u0048\u0038\u0032\u0054\u005e\u007a\u005a\u0068\u005e\u005b\u0029\u0035\u0046\u0031\u003e\u0036\u0022\u0078\u0032\u007e\u0052\u007a\u005b\u005e\u0040\u005e\u0061\u0040\u0078\u0021\u0034\u0039\u006e\u006c\u0042\u0042\u007d\u0052\u003f\u0048\u0064\u0066\u007d\u002b\u0069\u0036\u0073\u0044\u005e\u0061\u0072\u006d\u004f\u0026\u005f\u0069\u0025\u0048\u007d\u0055\u0037\u007c\u0054\u007c\u005b\u0074\u0035\u0072\u007a\u002b\u0076\u007a\u0022\u0069\u0059\u0058\u0038\u0075\u003b\u004f\u0031\u006c\u0042\u0040\u0072\u0072\u0076\u0065\u0041\u0078\u007d\u003b\u0070\u0056\u0021\u0048\u005e\u003f\u0061\u0063\u0072\u005e\u005e\u002c\u0033\u0073\u0025\u0064\u0070\u006e\u0054\u0058\u005e\u0059\u0061\u002e\u007a\u0024\u0077\u007c\u0048\u003a\u0071\u0057\u0038\u005a\u005b\u002e\u002a\u0060\u0079\u0043\u0046\u0048\u002a\u007c\u0048\u0041\u0055\u0039\u006a\u0076\u0032\u0060\u0046\u0076\u0068\u006c\u003a\u002f\u0042\u004c\u0061\u0068\u004c\u0022\u0047\u0051\u0049\u0034\u0069\u0032\u0073\u0075\u0028\u007d\u0038\u0058\u0054\u0067\u006e\u003b\u0035\u0046\u007a\u0071\u006a\u0069\u006b\u0041\u0044\u0021\u0049\u0048\u0021\u005a\u005a\u0025\u004b\u0046\u007a\u0048\u0077\u003b\u0048\u0047\u0077\u0070\u0031\u0038\u0075\u006a\u0064\u0061\u0057\u0066\u002e\u0030\u0057\u0064\u003f\u0055\u0059\u006f\u0047\u003a\u003b\u0037\u0037\u0069\u0061\u0073\u004e\u0043\u0057\u004a\u0033\u0025\u0059\u0061\u0040